@js:
const list = [];
const push = (title, url, size) =>
  list.push({
    title,
    url,
    style: {layout_flexBasisPercent: size}
  });

const fl = "分类::\n玄幻奇幻::/bsort1/\n武侠仙侠::/bsort2/\n都市生活::/bsort3/\n历史军事::/bsort4/\n游戏竞技::/bsort5/\n科幻未来::/bsort6/\n恐怖悬疑::/bsort7/\n其他类型::/bsort8/\n古代言情::/bsort9/\n现代言情::/bsort10/\n幻想奇缘::/bsort11/\n游戏情缘::/bsort12/\n浪漫青春::/bsort13/\n言情美文::/bsort14/\n科幻灵异::/bsort15/\n其他类型::/bsort16/";

fl.split("\n").forEach(x=>{
  let [title, url] = x.split("::");
  push(title, url, url ? 0.29 : 1)
})

var rank = "完结榜 - 男生小说::\n玄幻奇幻::/full/xuanhuan/\n武侠仙侠::/full/wuxia/\n都市生活::/full/dushi/\n历史军事::/full/lishi/\n游戏竞技::/full/youxi/\n科幻未来::/full/kehuan/\n恐怖悬疑::/full/xuanyi/\n其他类型::/full/qita/\n古代言情::/full/guyan/\n完结榜 - 女生小说::\n现代言情::/full/xianyan/\n幻想奇缘::/full/huanqing/\n游戏情缘::/full/zongcai/\n浪漫青春::/full/qingchun/\n言情美文::/full/wangluo/\n科幻灵异::/full/mmkehuan/\n其他类型::/full/mmqita/";

//若不能正常使用，删掉下面代码
const rankMap = {
	 热门榜: "/btopallvisit/0/{{page}}.htm",
  推荐榜: "/btopallvote/0/{{page}}.htm",
  收藏榜: "/btopgoodnum/0/{{page}}.htm",
  完结榜: ""
}

list.push({
        "title": "选择榜单",
        "type": "select",
        "action": "java.refreshExplore()",
        "chars": Object.keys(rankMap),
        "default": "完结榜",
        "style": {
            "layout_flexBasisPercent": 1
        }
})

let input = String(infoMap["选择榜单"]);
if(input == "完结榜"){
  rank.split("\n").forEach(x=>{
    let [title, url] = x.split("::");
    push(title, url, url ? 0.29 : 1)
  })
} else {
  push(input, rankMap[input], 0.9)
}
infoMap.save();
//若不正常，删掉上述代码

JSON.stringify(list)

